const fs = require('fs');
const path = '/home/zmhel/gitrepos/learn-ai/eval01/runs/.gen-work/t32/game.html';
const h = fs.readFileSync(path, 'utf8');
const js = h.match(/<script>([\s\S]*)<\/script>/)[1];
const cut = js.indexOf('   12. UI');
const core = js.slice(0, js.lastIndexOf('/* =====', cut));
const M = eval(core + '\n;({runTests,runBenchmark,computeScore,newGame,stateHash,TECH_ORDER})');

const r = M.runTests();
r.out.forEach((o, i) => console.log((o.ok ? 'PASS' : 'FAIL'), String(i + 1).padStart(2), o.name, '|', o.detail));
console.log('---', r.pass, 'passed,', r.fail, 'failed');

console.log('\n=== BENCHMARK 200 turns ===');
for (const seed of [1337, 2024, 7]) {
  const b1 = M.runBenchmark(seed, 200), b2 = M.runBenchmark(seed, 200);
  const B = b1.S;
  console.log('seed', seed, 'hash', b1.hash, b1.hash === b2.hash ? 'REPRODUCIBLE' : '*** MISMATCH ' + b2.hash,
    '| turn', B.turn, '| outcome', B.over, '| pop', B.people.length,
    '| tech', M.TECH_ORDER.filter(k => B.tech[k]).length,
    '| score', M.computeScore(B),
    '| food', Math.round(B.res.food), 'water', Math.round(B.res.water));
}

